@Command([EditDocument];"1");

@If (company= ""; @Return(@Do(@Command([EditGotoField];"company") ;@Prompt([Ok];"Missing Value"; "Please select the Company before proceeding!")));"");
@If (Recipient= ""; @Return(@Do(@Command([EditGotoField];"Recipient") ;@Prompt([Ok];"Missing Value"; "Please select the Recipient before proceeding!")));"");
@If (Recipient !="Customer" & Recipient !="Employee" & Name= ""; @Return(@Do(@Command([EditGotoField];"Name") ;@Prompt([Ok];"Missing Value"; "Please insert your Name before proceeding!")));"");

@If (Requestor= ""; @Return(@Do(@Command([EditGotoField];"Requestor") ;@Prompt([Ok];"Missing Value"; "Please state the Requestor before proceeding!")));"");
@If (Department= ""; @Return(@Do(@Command([EditGotoField];"Department") ;@Prompt([Ok];"Missing Value"; "Please select the Department before proceeding!")));"");
@If (Type= ""; @Return(@Do(@Command([EditGotoField];"Type") ;@Prompt([Ok];"Missing Value"; "Please insert your Type before proceeding!")));"");

@If (Purpose= ""; @Return(@Do(@Command([EditGotoField];"Purpose") ;@Prompt([Ok];"Missing Value"; "Please select the Purpose before proceeding!")));"");
@If (IsBenefit= ""; @Return(@Do(@Command([EditGotoField];"IsBenefit") ;@Prompt([Ok];"Missing Value"; "Is the Gift benefit to Company?!")));"");
@If (IsLogo= ""; @Return(@Do(@Command([EditGotoField];"IsLogo") ;@Prompt([Ok];"Missing Value"; "Is the item with Company logo?")));"");

@If (Quantity= ""; @Return(@Do(@Command([EditGotoField];"Quantity") ;@Prompt([Ok];"Missing Value"; "Please state the Quantity before proceeding!")));"");
@If (Price= ""; @Return(@Do(@Command([EditGotoField];"Price") ;@Prompt([Ok];"Missing Value"; "Please select the Price before proceeding!")));"");
@If (CC= ""; @Return(@Do(@Command([EditGotoField];"CC") ;@Prompt([Ok];"Missing Value"; "Please include Division Head in the CC before proceeding!")));"");

FIELD Notified := @V3UserName;
FIELD reportedDate :=@Today;
FIELD CurrentAction :="Submitted";

@Command([FileSave]);

@MailSend(HR;MailList;NULL;"New Gift/Donation/Sponsorship Requisition : "  +  INO ;NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

