@Command([EditDocument];"1");

@If (ReqType=""; @Return(@Do(@Command([EditGotoField];"ReqType") ;@Prompt([Ok];"Missing Value"; "Please select the Request Type!")));"");
@If (company= ""; @Return(@Do(@Command([EditGotoField];"company") ;@Prompt([Ok];"Missing Value"; "Please select the Company!")));"");
@If (Recipient= ""; @Return(@Do(@Command([EditGotoField];"Recipient") ;@Prompt([Ok];"Missing Value"; "Please select the Recipient!")));"");
@If (Name= ""; @Return(@Do(@Command([EditGotoField];"Name") ;@Prompt([Ok];"Missing Value"; "Please state the Name!")));"");
@If (Address= ""; @Return(@Do(@Command([EditGotoField];"Address") ;@Prompt([Ok];"Missing Value"; "Please state the Address!")));"");
@If (ReqType="Requestor" & Requestor= ""; @Return(@Do(@Command([EditGotoField];"Requestor") ;@Prompt([Ok];"Missing Value"; "Please state the Requestor!")));"");
@If (HOD= ""; @Return(@Do(@Command([EditGotoField];"HOD") ;@Prompt([Ok];"Missing Value"; "Please select the HOD name!")));"");

@If (Department= ""; @Return(@Do(@Command([EditGotoField];"Department") ;@Prompt([Ok];"Missing Value"; "Please select the Department!")));"");
@If (Type= ""; @Return(@Do(@Command([EditGotoField];"Type") ;@Prompt([Ok];"Missing Value"; "Please insert your Type!")));"");
@If (Purpose= ""; @Return(@Do(@Command([EditGotoField];"Purpose") ;@Prompt([Ok];"Missing Value"; "Please select the Purpose!")));"");
@If (@Member("Others";Purpose) != 0 & Purpose= ""; @Return(@Do(@Command([EditGotoField];"Purpose") ;@Prompt([Ok];"Missing Value"; "Please state the other Purpose!")));"");

@If (ReqType="Requestor" & Purpose= ""; @Return(@Do(@Command([EditGotoField];"Purpose") ;@Prompt([Ok];"Missing Value"; "Please select the Purpose!")));"");
@If (ReqType="Requestor" & IsBenefit= ""; @Return(@Do(@Command([EditGotoField];"IsBenefit") ;@Prompt([Ok];"Missing Value"; "Is the Gift benefit to Company?!")));"");
@If (ReqType="Requestor" & IsLogo= ""; @Return(@Do(@Command([EditGotoField];"IsLogo") ;@Prompt([Ok];"Missing Value"; "Is the item with Company logo?")));"");

@If (ReqType="Requestor" & Quantity= ""; @Return(@Do(@Command([EditGotoField];"Quantity") ;@Prompt([Ok];"Missing Value"; "Please state the Quantity!")));"");
@If (ReqType="Requestor" & Price= ""; @Return(@Do(@Command([EditGotoField];"Price") ;@Prompt([Ok];"Missing Value"; "Please select the Price!")));"");
@If (position= ""; @Return(@Do(@Command([EditGotoField];"position") ;@Prompt([Ok];"Missing Value"; "Please enter your position!")));"");

FIELD Notified := @V3UserName;
FIELD reportedDate :=@Today;
FIELD CA :="Submitted";

@Command([FileSave]);

@MailSend(HOD;HR:MailList;NULL;"New Gift/Donation/Sponsorship Requisition : "  +  INO ;NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

